INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A anatomia da superfície do dorso permite a identificação de pontos de referência importantes. Ao palpar o processo espinhoso mais proeminente na base do pescoço quando o paciente flexiona a cabeça, o examinador identifica a vértebra tecnicamente chamada de \"vértebra proeminente\". Qual é a numeração correta dessa vértebra?","options":{"a":"C5.","b":"C6.","c":"C7.","d":"T1.","e":"T2."},"answer":"c","rationale":"A 7ª vértebra cervical (C7) possui um processo espinhoso longo, não bifurcado e muito proeminente, o que a torna um marco anatômico fundamental para a contagem das vértebras no exame físico do dorso. Embora o processo espinhoso de T1 também seja proeminente, o de C7 é o ponto de referência clássico descrito na anatomia sistemática como \"vértebra proeminens\".","option_rationales":{"a":"Errada. C5 não é proeminente ao toque superficial.","b":"Errada. C6 é identificada pelo tubérculo carótico, mas não pelo processo espinhoso no dorso.","c":"Correta. C7 é a definição técnica de vértebra proeminente.","d":"Errada. T1 é proeminente, mas situa-se logo abaixo da C7.","e":"Errada. T2 é oculta pela musculatura do trapézio superior."},"difficulty":"Fácil","tags":["Anatomia","Coluna Vertebral","Osteologia"]}', '2fff583fd1f616feebb9ded637c4c52c', 10, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A respiração paradoxal é um sinal clínico de grave insuficiência respiratória ou lesão traumática (como o tórax instável). Em recém-nascidos, devido à complacência da caixa torácica, a inspiração pode causar retrações intercostais. Do ponto de vista anatômico, o movimento de \"alça de balde\" (bucket handle), que aumenta o diâmetro lateral (transverso) do tórax durante a inspiração, é realizado predominantemente por quais costelas?","options":{"a":"1ª e 2ª costelas.","b":"3ª a 6ª costelas.","c":"7ª a 10ª costelas.","d":"11ª e 12ª costelas.","e":"Apenas as costelas flutuantes."},"answer":"c","rationale":"Existem dois movimentos clássicos das costelas na inspiração: o \"braço de bomba\" (pump handle), que eleva as extremidades anteriores das costelas superiores (2-6) aumentando o diâmetro anteroposterior; e a \"alça de balde\" (bucket handle), típico das costelas inferiores (7-10), cujas partes laterais se elevam e se afastam da linha média, aumentando o diâmetro transverso. As flutuantes (11-12) têm pouco papel mecânico direto na expansão volumétrica.","option_rationales":{"a":"Errada. As costelas superiores fazem movimento de \"braço de bomba\".","b":"Errada. Costelas 3-6 aumentam principalmente o diâmetro anteroposterior.","c":"Correta. 7ª a 10ª realizam o movimento de alça de balde.","d":"Errada. 11ª e 12ª são flutuantes e não fixas ao esterno.","e":"Errada. As flutuantes não contribuem para o movimento de alça de balde eficiente."},"difficulty":"Difícil","tags":["Anatomia","Tórax","Biomecânica"]}', '3a80719a758087c8edd98a50406c3714', 11, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente submetido a uma nefrectomia radical por via lombar (incisão de lombo-laparotomia) apresenta, no pós-operatório, uma fraqueza na musculatura abdominal anterolateral e perda de sensibilidade na região suprapúbica. O cirurgião suspeita de lesão nervosa durante a incisão muscular profunda. Qual nervo, que percorre a face anterior do músculo quadrado lombar e perfura o músculo transverso do abdome, é o mais provável de ter sido lesado?","options":{"a":"Nervo femoral.","b":"Nervo ilio-hipogástrico.","c":"Nervo obturador.","d":"Nervo genitofemoral.","e":"Nervo subcostal."},"answer":"b","rationale":"O nervo ilio-hipogástrico (L1) emerge da borda lateral do psoas maior, passa anteriormente ao quadrado lombar e perfura o transverso do abdome próximo à crista ilíaca. Ele supre os músculos da parede abdominal e fornece sensibilidade à pele da região glútea lateral e suprapúbica. Sua localização o torna vulnerável em incisões lombares ou renais.","option_rationales":{"a":"Errada. O nervo femoral é profundo e emerge entre o psoas e o ilíaco, dirigindo-se à coxa.","b":"Correta. Sua topografia condiz com o risco em cirurgias renais via lombar.","c":"Errada. O nervo obturador corre medialmente ao psoas para o forame obturado.","d":"Errada. O genitofemoral perfura o músculo psoas na sua face anterior.","e":"Errada. O subcostal (T12) corre logo abaixo da 12ª costela; embora vulnerável, o relato de parestesia suprapúbica aponta mais para L1."},"difficulty":"Difícil","tags":["Anatomia","Plexo Lombar","Parede Abdominal"]}', '6439406d36811e57cfc8762f59197ce0', 12, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O canal vertebral contém a medula espinal, as meninges e as raízes nervosas. Em um adulto jovem saudável, em qual nível vertebral a medula espinal geralmente termina, dando início à cauda equina?","options":{"a":"L1 - L2.","b":"L4 - L5.","c":"S1 - S2.","d":"T10 - T11.","e":"No nível do cóccix."},"answer":"a","rationale":"No feto, a medula ocupa toda a extensão do canal vertebral. Devido ao crescimento diferencial da coluna vertebral e do tecido nervoso (ascensão aparente da medula), no adulto, o cone medular (final da medula espinal) situa-se geralmente no nível do disco intervertebral entre L1 e L2. Por isso, punções lombares são realizadas com segurança abaixo deste nível (ex: L3-L4 ou L4-L5).","option_rationales":{"a":"Correta. Nível fisiológico padrão no adulto.","b":"Errada. Nível comum para punção lombar, já no espaço da cauda equina.","c":"Errada. S1-S2 é o nível onde termina o saco dural, não a medula.","d":"Errada. Nível muito elevado; a medula continua abaixo de T12.","e":"Errada. Incorreto; a medula termina muito antes do cóccix no adulto."},"difficulty":"Fácil","tags":["Anatomia","Medula Espinal","Neuroanatomia"]}', '60e7102d6abbd78f91e8bfe5cb6c9d78', 13, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As costelas são classificadas como verdadeiras, falsas ou flutuantes baseadas em sua fixação ao esterno. Um paciente com dor torácica localizada na junção das cartilagens costais com o esterno (condrite) é avaliado. Anatômica e sistematicamente, quais são as costelas consideradas \"verdadeiras\" (vertebrocostais)?","options":{"a":"1ª a 5ª costelas.","b":"1ª a 7ª costelas.","c":"1ª a 10ª costelas.","d":"8ª a 10ª costelas.","e":"11ª e 12ª costelas."},"answer":"b","rationale":"Costelas verdadeiras (1ª-7ª) são aquelas cujas cartilagens costais se articulam diretamente com o esterno. As falsas (8ª-10ª) têm suas cartilagens unidas à cartilagem da costela imediatamente superior, formando a margem costal. As flutuantes (11ª-12ª) não possuem fixação anterior, terminando na musculatura abdominal posterior.","option_rationales":{"a":"Errada. Incompleto, a 6ª e 7ª também são verdadeiras.","b":"Correta. Classificação clássica das costelas vertebrocostais.","c":"Errada. Inclui as costelas falsas (8-10).","d":"Errada. Estas são as costelas falsas.","e":"Errada. Estas são as costelas flutuantes."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Osteologia"]}', 'ac4a0e48397be0e361657ff4009f09d2', 14, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo grande dorsal (latissimus dorsi) é um dos maiores e mais superficiais músculos do dorso. Ele possui uma origem extensa e se insere no úmero. Sabendo que este músculo é clinicamente testado pedindo ao paciente para aduzir o braço contra resistência (movimento de \"coçar as costas\"), identifique o nervo responsável por sua inervação.","options":{"a":"Nervo acessório (XI par).","b":"Nervo dorsal da escápula.","c":"Nervo toracodorsal.","d":"Nervo torácico longo.","e":"Nervos intercostais."},"answer":"c","rationale":"O músculo grande dorsal é inervado pelo nervo toracodorsal (ramo do fascículo posterior do plexo braquial, raízes C6, C7, C8). Lesões desse nervo (por exemplo, em cirurgias de esvaziamento axilar por câncer de mama) resultam em fraqueza na extensão, adução e rotação medial do úmero.","option_rationales":{"a":"Errada. O nervo acessório inerva o trapézio e o esternocleidomastoideo.","b":"Errada. O dorsal da escápula inerva os romboides e o levantador da escápula.","c":"Correta. Nervo específico para o músculo grande dorsal.","d":"Errada. O torácico longo inerva o músculo serrátil anterior.","e":"Errada. O grande dorsal é um músculo extrínseco do dorso derivado do membro superior, não sendo inervado por ramos segmentares do tronco."},"difficulty":"Média","tags":["Anatomia","Músculos","Plexo Braquial"]}', '3ea75ab564c09e0135b3802c2c541d79', 15, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A herniação de disco intervertebral ocorre mais frequentemente em direção posterolateral devido a uma característica anatômica específica dos ligamentos da coluna vertebral. Qual ligamento reforça a face anterior dos corpos vertebrais e discos, mas torna-se estreito e menos resistente na sua porção posterior?","options":{"a":"Ligamento longitudinal anterior.","b":"Ligamento longitudinal posterior.","c":"Ligamento amarelo.","d":"Ligamento nucal.","e":"Ligamento supraespinal."},"answer":"b","rationale":"O ligamento longitudinal anterior é largo e forte, cobrindo a face anterior dos corpos vertebrais. Já o ligamento longitudinal posterior percorre o interior do canal vertebral; ele é mais estreito e fraco, especialmente nas margens posterolaterais dos discos intervertebrais. Essa \"fraqueza\" anatômica lateral ao ligamento posterior é o caminho de menor resistência para o núcleo pulposo herniar.","option_rationales":{"a":"Errada. O longitudinal anterior é extremamente forte e largo.","b":"Correta. Sua conformação estreita predispõe a hérnias posterolaterais.","c":"Errada. O ligamento amarelo está no arco vertebral, não no corpo.","d":"Errada. Ligamento cervical posterior.","e":"Errada. Conecta os processos espinhosos."},"difficulty":"Média","tags":["Anatomia","Coluna Vertebral","Patologia Anatômica"]}', 'cec636be8cf52bb2e9a776dc035ad3e1', 16, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Uma criança de 4 anos aspira acidentalmente um pequeno brinquedo de plástico. O exame radiográfico sugere que o corpo estranho está alojado em um dos brônquios principais. De acordo com a anatomia da árvore brônquica, em qual brônquio o objeto tem maior probabilidade de ser encontrado?","options":{"a":"Brônquio principal esquerdo, por ser mais horizontal e largo.","b":"Brônquio principal direito, por ser mais vertical, mais curto e mais largo.","c":"Brônquio principal esquerdo, por ser mais longo e estreito.","d":"Brônquio principal direito, por ser mais longo e horizontal.","e":"Ambos têm a mesma probabilidade anatômica."},"answer":"b","rationale":"O brônquio principal direito é mais vertical (forma ângulo menos agudo com a traqueia), mais curto (aproximadamente 2,5 cm) e mais largo que o esquerdo. Essas características anatômicas facilitam a passagem de corpos estranhos aspirados, que tendem a seguir a trajetória retilínea da traqueia para o pulmão direito.","option_rationales":{"a":"Errada. O esquerdo é mais horizontal, o que dificulta o alojamento de objetos.","b":"Correta. Morfologia clássica que explica a epidemiologia da aspiração.","c":"Errada. Características corretas do esquerdo, mas que diminuem a chance de aspiração.","d":"Errada. O direito é curto e vertical.","e":"Errada. Há uma clara predisposição anatômica para o lado direito."},"difficulty":"Fácil","tags":["Anatomia","Sistema Respiratório","Clínica."]}', '0c7e624b3565434d3d79aaa1a55de131', 17, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As articulações sinoviais dos processos articulares da coluna vertebral, que permitem movimentos de deslizamento entre vértebras adjacentes, são conhecidas como:","options":{"a":"Sinfises intervertebrais.","b":"Articulações uncovertebrais (de Luschka).","c":"Articulações zigapofisárias.","d":"Sindesmoses interlaminares.","e":"Esquindileses cervicais."},"answer":"c","rationale":"As articulações zigapofisárias (ou articulações de facetas) são articulações sinoviais planas entre os processos articulares superior de uma vértebra e inferior da vértebra sobrejacente. Elas determinam o tipo de movimento permitido em cada região da coluna (ex: rotação na torácica, flexão/extensão na lombar). Degenerações nessas articulações são causas comuns de dor nas costas crônica.","option_rationales":{"a":"Errada. Sinfises referem-se aos discos entre os corpos vertebrais (cartilaginosas).","b":"Errada. Estas ocorrem apenas na região cervical entre os processos uncinados.","c":"Correta. Nomenclatura anatômica padrão para as facetas articulares.","d":"Errada. Sindesmoses interlaminares referem-se à união pelos ligamentos amarelos.","e":"Errada. Esquindilese é um tipo de articulação fibrosa rara (ex: vômer com esfenoide)."},"difficulty":"Média","tags":["Anatomia","Artrologia","Coluna Vertebral"]}', '9be3906e45f1937c183d0d510123ff1f', 18, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo psoas maior é um músculo volumoso que compõe a parede abdominal posterior. Ele tem origem nos processos transversos e corpos das vértebras lombares (T12-L5). Sabendo que seu tendão se une ao músculo ilíaco para se inserir no fêmur, identifique o seu local de inserção distal e a sua função principal no quadril.","options":{"a":"Trocânter maior; Extensão do quadril.","b":"Trocânter menor; Flexão do quadril.","c":"Linha áspera; Adução do quadril.","d":"Epicôndilo medial; Rotação externa do joelho.","e":"Tuberosidade isquiática; Estabilização da pélvis."},"answer":"b","rationale":"O músculo iliopsoas (fusão do psoas maior e ilíaco) é o flexor mais potente do quadril. Ele se insere distalmente no trocânter menor do fêmur. Além da flexão do quadril, ele atua na flexão do tronco e na estabilização da postura ereta. É um músculo clinicamente importante, pois abscessos de coluna (ex: mal de Pott) podem drenar através de sua fáscia até a coxa.","option_rationales":{"a":"Errada. O trocânter maior é local de inserção de glúteos e rotadores externos; o psoas não estende o quadril.","b":"Correta. Inserção no trocânter menor e função de flexão.","c":"Errada. Músculos adutores inserem-se na linha áspera.","d":"Errada. Foge totalmente da anatomia do psoas.","e":"Errada. A tuberosidade isquiática é origem dos hamstrings (isquiotibiais)."},"difficulty":"Fácil","tags":["Anatomia","Músculos","Membro Inferior"]}', 'dff5804a0707541d7341abfe7aa65f36', 19, 'draft');